const places = $input.item.json.places || [];
const region = $('Set Regional Search Query').item.json.region || 'Nea Kallikrateia';
const output = [];

for (const p of places) {
  let rawPhone = p.phoneNumber || '';
  let cleanPhone = rawPhone.replace(/[^0-9+]/g, '');
  if (cleanPhone.startsWith('69') && cleanPhone.length === 10) cleanPhone = '+30' + cleanPhone;
  else if (cleanPhone.startsWith('30') && !cleanPhone.startsWith('+')) cleanPhone = '+' + cleanPhone;

  let website = p.website || '';
  if (website.includes('booking.com') || website.includes('airbnb.') || website.includes('tripadvisor.')) {
    website = '';
  }

  // Only take entries with valid phones
  if (cleanPhone.length >= 8) {
    output.push({
      json: {
        property_name: p.title || 'Greek Vacation Rental',
        phone: cleanPhone,
        website: website,
        address: p.address || 'Nea Kallikrateia, Halkidiki',
        rating: p.rating || 4.8,
        reviews_count: p.ratingCount || 10,
        region: region
      }
    });
  }
}

return output;

let text = '';
if ($input.item.json.output && $input.item.json.output[0] && $input.item.json.output[0].content) {
  text = $input.item.json.output[0].content[0].text || '';
} else if ($input.item.json.text) {
  text = $input.item.json.text;
} else if (typeof $input.item.json === 'string') {
  text = $input.item.json;
} else {
  text = JSON.stringify($input.item.json);
}

text = text.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed = {};
try {
  parsed = JSON.parse(text);
} catch(e) {
  parsed = { property_name: 'Greek Rental', notes: text, status: 'ai_audited' };
}

return { json: parsed };
